<?php
/**
 * SaaS Settings > E-commerce > General Settings (safe installer).
 * Usage: php ecommerce_general_settings_move_patch.php --dry-run | --apply | --rollback=BACKUP_ID
 * Modifies only the explicit manifest paths. No database queries are executed here.
 */

declare(strict_types=1);
$root = __DIR__;
if (!is_file($root.'/artisan')) { fwrite(STDERR, "Run this patch from your Laravel project root (beside artisan).\n"); exit(1); }
$payload = '';
$files = json_decode((string) base64_decode($payload, true), true, 512, JSON_THROW_ON_ERROR);
$args = array_slice($argv, 1);
$apply = in_array('--apply', $args, true);
$dryRun = in_array('--dry-run', $args, true);
$rollback = null;
foreach ($args as $arg) if (str_starts_with($arg, '--rollback=')) $rollback = substr($arg, 11);
if (!$apply && !$dryRun && $rollback === null) {
    echo "Usage:\n  php ".basename(__FILE__)." --dry-run\n  php ".basename(__FILE__)." --apply\n  php ".basename(__FILE__)." --rollback=BACKUP_ID\n";
    exit(0);
}
$backupRoot = $root.'/.patch_backups/ecommerce_settings_move';
function hashText(string $s): string { return hash('sha256', $s); }
function patchAdminRoutes(string $s): string
{
    $require = "            require __DIR__.'/Settings/Ecommerce/GeneralSettings/routes.php';";
    if (str_contains($s, "Settings/Ecommerce/GeneralSettings/routes.php")) return $s;
    $anchor = "            require __DIR__.'/Settings/Business/Branding/routes.php';";
    if (substr_count($s, $anchor) !== 1) throw new RuntimeException('Cannot locate the Business Branding route anchor in admin.php');
    return str_replace($anchor, $anchor."\n".$require, $s);
}
function patchSeeder(string $s): string
{
    $end = strpos($s, '// Reusable category profiles:');
    $begin = $end === false ? false : strrpos(substr($s, 0, $end), "['settings','Settings','সেটিংস','settings',[");
    if ($begin === false || $end === false) throw new RuntimeException('Cannot locate the Settings module inside ModuleMenuSeeder.');
    $chunk = substr($s, $begin, $end-$begin);
    if (!preg_match("/\\['ecommerce'\\s*,/u", $chunk)) {
        $menu = "                ['ecommerce','E-commerce','ই-কমার্স','shopping-bag',[[ 'general-settings','General Settings','সাধারণ সেটিংস',null]]],";
        $pattern = "/^([ \\t]*\\['business'\\s*,[^\\r\\n]*\\],)\\R/mu";
        if (!preg_match($pattern, $chunk)) throw new RuntimeException('Cannot identify the Settings > Business menu row in ModuleMenuSeeder.');
        $chunk = preg_replace_callback($pattern, fn($m) => $m[1]."\n".$menu."\n", $chunk, 1);
        $s = substr($s, 0, $begin).$chunk.substr($s, $end);
    }
    $mappingAt = strpos($s, "'settings'=>['navigation-management'");
    if ($mappingAt === false) throw new RuntimeException('Cannot locate the Settings category profile mapping.');
    $mappingEnd = strpos($s, '],', $mappingAt);
    if ($mappingEnd === false) throw new RuntimeException('Malformed Settings category mapping.');
    $mapping = substr($s, $mappingAt, $mappingEnd-$mappingAt);
    if (!preg_match("/'ecommerce'\\s*=>/u", $mapping)) {
        $updated = preg_replace("/'business'\\s*=>\\s*'\\*'\\s*,/u", "'business'=>'*','ecommerce'=>'*',", $mapping, 1, $n);
        if ($n !== 1) throw new RuntimeException('Cannot safely append E-commerce entitlement to category settings mapping.');
        $s = substr($s, 0, $mappingAt).$updated.substr($s, $mappingEnd);
    }
    return $s;
}
function safePath(string $root, string $relative): string
{
    if ($relative==='' || str_contains($relative, '..') || str_starts_with($relative, '/') || str_contains($relative, '\\')) {
        throw new RuntimeException('Unsafe manifest path.');
    }
    return $root.'/'.$relative;
}
function writeSafely(string $path, string $content): void
{
    $parent = dirname($path);
    if (!is_dir($parent) && !mkdir($parent, 0775, true) && !is_dir($parent)) throw new RuntimeException('Unable to create directory '.$parent);
    $tmp = tempnam($parent, '.patch-');
    if (!$tmp || file_put_contents($tmp, $content) === false) throw new RuntimeException('Cannot write '.$path);
    @chmod($tmp, 0644);
    if (!@rename($tmp, $path)) {
        // Windows may refuse to rename over an existing destination.
        if (!is_file($path) || file_put_contents($path, $content, LOCK_EX) !== strlen($content)) {
            @unlink($tmp); throw new RuntimeException('Cannot replace '.$path);
        }
        @unlink($tmp);
    }
}
if ($rollback !== null) {
    if (!preg_match('/^\\d{8}_\\d{6}_[a-f0-9]{6}$/', $rollback)) throw new RuntimeException('Invalid backup ID.');
    $dir = $backupRoot.'/'.$rollback;
    $manifest = json_decode((string) @file_get_contents($dir.'/manifest.json'), true);
    if (!is_array($manifest) || !isset($manifest['changed'])) throw new RuntimeException('Backup manifest missing for '.$rollback);
    foreach ($manifest['changed'] as $name=>$entry) {
        $destination = safePath($root, $name);
        $now = is_file($destination) ? file_get_contents($destination) : null;
        if ($now === null || hashText($now) !== $entry['installed_sha256']) throw new RuntimeException('ROLLBACK CONFLICT: '.$name.' has been edited since installation. No files rolled back.');
    }
    foreach ($manifest['changed'] as $name=>$entry) {
        $destination = safePath($root, $name);
        if ($entry['was_present']) {
            $old = file_get_contents($dir.'/originals/'.$name);
            if ($old === false) throw new RuntimeException('Backup file missing for '.$name);
            writeSafely($destination, $old);
        } else {
            if (!unlink($destination)) throw new RuntimeException('Cannot remove '.$name);
        }
        echo "RESTORED  {$name}\n";
    }
    echo "ROLLBACK OK\n";
    exit(0);
}
$changes = [];
$errors = [];
foreach ($files as $name=>$entry) {
    try {
        $path = safePath($root, $name);
        if (is_link($path)) throw new RuntimeException('Symlink path refused');
        $old = is_file($path) ? file_get_contents($path) : null;
        if ($old === false) throw new RuntimeException('File cannot be read');
        $target = (string)base64_decode($entry['content'], true);
        if ($entry['mode'] === 'dynamic_routes') {
            if ($old === null) throw new RuntimeException('Route file is missing');
            $target = patchAdminRoutes($old);
        } elseif ($entry['mode'] === 'dynamic_seeder') {
            if ($old === null) throw new RuntimeException('Seeder file is missing');
            $target = patchSeeder($old);
        } elseif ($old !== null && hashText($old) !== $entry['old_sha256'] && hashText($old) !== $entry['new_sha256']) {
            throw new RuntimeException('Local file differs from the reviewed project; merge manually instead of overwriting');
        }
        if (hashText($target) === hashText((string)$old) && $old !== null) { echo "UNCHANGED {$name}\n"; continue; }
        if ($entry['old_sha256'] === null && $old !== null && hashText($old) !== hashText($target)) throw new RuntimeException('New source path already exists with different code');
        $changes[$name] = ['before'=>$old,'after'=>$target];
        echo ($old === null ? 'CREATE   ' : 'UPDATE   ').$name."\n";
    } catch (Throwable $error) { $errors[] = "CONFLICT {$name}: {$error->getMessage()}"; }
}
if ($errors) { foreach ($errors as $msg) fwrite(STDERR, $msg."\n"); exit(2); }
if ($dryRun) { echo "DRY RUN OK; ".count($changes)." file(s) to write.\n"; exit(0); }
if (!$changes) { echo "ALREADY APPLIED; nothing to change.\n"; exit(0); }
$id = date('Ymd_His').'_'.substr(bin2hex(random_bytes(3)), 0, 6);
$dir = $backupRoot.'/'.$id;
if (!mkdir($dir.'/originals', 0775, true) && !is_dir($dir.'/originals')) throw new RuntimeException('Cannot create backup directory.');
$manifest = ['source'=>'ecommerce_settings_move','changed'=>[]];
foreach ($changes as $name=>$entry) {
    $manifest['changed'][$name] = ['was_present'=>$entry['before'] !== null, 'installed_sha256'=>hashText($entry['after'])];
    if ($entry['before'] !== null) {
        $dest = $dir.'/originals/'.$name;
        $parent = dirname($dest);
        if (!is_dir($parent)) mkdir($parent, 0775, true);
        if (file_put_contents($dest, $entry['before']) === false) throw new RuntimeException('Cannot back up '.$name);
    }
}
if (file_put_contents($dir.'/manifest.json', json_encode($manifest, JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)) === false) throw new RuntimeException('Cannot write backup manifest.');
$written=[];
try {
    foreach ($changes as $name=>$entry) {
        writeSafely(safePath($root, $name), $entry['after']);
        $written[] = $name;
    }
} catch (Throwable $e) {
    foreach (array_reverse($written) as $name) {
        $old = $changes[$name]['before'];
        if ($old === null) @unlink(safePath($root, $name));
        else writeSafely(safePath($root, $name), $old);
    }
    throw $e;
}
echo "APPLY OK: ".count($changes)." file(s).\nBACKUP_ID={$id}\n";
echo "NEXT:\n  php artisan migrate --force\n  php artisan optimize:clear\n";
echo "For code-only rollback: php ".basename(__FILE__)." --rollback={$id}\n";
